const PREGUNTAS = [
  { id:1, categoria:"senales", pregunta:"Que indica una senal de PARE (octagono rojo)?", opciones:["Reducir la velocidad y continuar si no hay peligro","Detencion obligatoria antes de la linea de pare","Ceder el paso a peatones solamente","Detencion opcional segun el trafico"], respuesta:1, explicacion:"La senal PARE obliga a detener completamente el vehiculo y ceder el paso a todo trafico antes de continuar." },
  { id:2, categoria:"senales", pregunta:"Que indica la senal CEDA EL PASO (triangulo invertido)?", opciones:["Detencion obligatoria","Prohibido el paso","Reducir la velocidad y ceder el paso al trafico que cruza","Velocidad maxima 30 km/h"], respuesta:2, explicacion:"CEDA EL PASO indica que el conductor debe ceder el paso a los vehiculos de la via preferencial." },
  { id:3, categoria:"senales", pregunta:"Que significa una senal circular con borde rojo y el numero 60?", opciones:["Velocidad minima 60 km/h","Velocidad maxima 60 km/h","Zona escolar maximo 60 km/h","Distancia al proximo control de velocidad"], respuesta:1, explicacion:"Las senales circulares con borde rojo son de prohibicion. En este caso la velocidad maxima permitida es 60 km/h." },
  { id:4, categoria:"senales", pregunta:"Que indica una senal con flecha y borde rojo que prohibe girar?", opciones:["Curva peligrosa a la derecha","Prohibido girar en la direccion indicada","Paso peatonal proximo","Zona de obras"], respuesta:1, explicacion:"Esta senal de prohibicion indica que esta prohibido girar en la direccion indicada por la flecha." },
  { id:5, categoria:"senales", pregunta:"Que color tienen las senales de informacion de servicios en Chile?", opciones:["Azul con letras blancas","Verde con letras blancas","Cafe con letras blancas","Amarillo con letras negras"], respuesta:0, explicacion:"Las senales de servicios (gasolineras, hospitales, hoteles) son de color azul con letras blancas." },
  { id:6, categoria:"senales", pregunta:"Que indica una senal triangular roja con un nino corriendo?", opciones:["Prohibido el paso de ninos","Zona escolar - precaucion con ninos","Parque infantil a la derecha","Velocidad maxima 20 km/h"], respuesta:1, explicacion:"Esta senal de advertencia triangular indica zona escolar. Se debe extremar precauciones y reducir velocidad." },
  { id:7, categoria:"senales", pregunta:"Una linea continua en el centro de la calzada significa:", opciones:["Se puede adelantar con precaucion","Prohibido cruzar la linea para adelantar","Separacion de carriles de igual direccion","Zona de estacionamiento permitido"], respuesta:1, explicacion:"Una linea continua en el eje de la calzada prohibe cruzarla para adelantar u otras maniobras." },
  { id:8, categoria:"senales", pregunta:"Que indica una senal circular roja de SENTIDO CONTRARIO?", opciones:["Prohibido el estacionamiento","Cruce ferroviario peligroso","Prohibido el ingreso en esa direccion","Prohibido adelantar"], respuesta:2, explicacion:"Esta senal indica sentido contrario, prohibiendo el ingreso de vehiculos en esa direccion." },
  { id:9, categoria:"normas", pregunta:"En una interseccion sin senalizacion quien tiene preferencia de paso?", opciones:["El vehiculo que llega primero","El vehiculo que viene por la derecha","El vehiculo mas grande","El vehiculo que va mas rapido"], respuesta:1, explicacion:"En Chile en intersecciones sin senalizacion tiene preferencia el vehiculo que viene por la derecha del conductor." },
  { id:10, categoria:"normas", pregunta:"Cual es la velocidad maxima en zonas urbanas en Chile?", opciones:["40 km/h","50 km/h","60 km/h","70 km/h"], respuesta:1, explicacion:"La velocidad maxima en zonas urbanas en Chile es de 50 km/h salvo senalizacion distinta." },
  { id:11, categoria:"normas", pregunta:"Nivel maximo de alcohol permitido para conducir en Chile (g/L en sangre)?", opciones:["0.3 g/L","0.5 g/L","0.8 g/L","0 g/L - tolerancia cero"], respuesta:0, explicacion:"La ley establece 0.3 g/L de alcohol en sangre. Para conductores novatos y transporte publico es tolerancia cero." },
  { id:12, categoria:"normas", pregunta:"Es obligatorio el cinturon de seguridad en Chile?", opciones:["Solo para el conductor","Para el conductor y el copiloto","Para todos los ocupantes del vehiculo","Solo en carreteras"], respuesta:2, explicacion:"En Chile es obligatorio el cinturon de seguridad para TODOS los ocupantes del vehiculo." },
  { id:13, categoria:"normas", pregunta:"A que distancia minima de un cruce peatonal esta prohibido estacionar?", opciones:["3 metros","5 metros","8 metros","10 metros"], respuesta:1, explicacion:"Esta prohibido estacionar a menos de 5 metros de un cruce peatonal." },
  { id:14, categoria:"normas", pregunta:"Cuando esta permitido adelantar a otro vehiculo?", opciones:["Cuando hay linea continua y hay espacio","Solo cuando hay linea discontinua y visibilidad suficiente","Siempre que el vehiculo de adelante vaya lento","En cualquier momento si se hace rapido"], respuesta:1, explicacion:"El adelantamiento solo esta permitido con linea discontinua y suficiente visibilidad y espacio." },
  { id:15, categoria:"normas", pregunta:"Que se debe hacer al aproximarse a una ambulancia con sirena encendida?", opciones:["Acelerar para dejarla pasar","Mantener la velocidad","Detenerse o desplazarse hacia la derecha para abrir paso","Seguir detras de ella"], respuesta:2, explicacion:"Ante vehiculos de emergencia con sirena activa se debe desplazarse hacia la derecha para abrir un corredor." },
  { id:16, categoria:"normas", pregunta:"Cuando se deben usar las luces antiniebla?", opciones:["Siempre que llueva","Solo de noche","Cuando la visibilidad es inferior a 200 metros","En zonas urbanas con poca iluminacion"], respuesta:2, explicacion:"Las luces antiniebla se usan cuando la visibilidad cae por debajo de 200 metros por niebla o lluvia intensa." },
  { id:17, categoria:"normas", pregunta:"Cual es la distancia minima de seguimiento segura recomendada?", opciones:["La regla de los 2 segundos","10 metros por cada 10 km/h","30 metros fijos","Depende del vehiculo"], respuesta:0, explicacion:"La regla de los 2 segundos: al menos 2 segundos de distancia entre tu vehiculo y el de adelante. En lluvia 4 segundos." },
  { id:18, categoria:"normas", pregunta:"Que se debe hacer si el semaforo esta en rojo y se quiere girar a la derecha?", opciones:["Se puede girar directamente","Detenerse ceder el paso y girar solo si hay senal que lo permita","Se puede girar si no hay peatones","Siempre esta prohibido girar con rojo"], respuesta:1, explicacion:"El giro a la derecha con rojo esta permitido solo si existe una senal especifica que lo indique." },
  { id:19, categoria:"normas", pregunta:"Cual es la velocidad maxima en autopistas en Chile?", opciones:["80 km/h","100 km/h","110 km/h","120 km/h"], respuesta:3, explicacion:"La velocidad maxima en autopistas y carreteras en Chile es de 120 km/h salvo senalizacion distinta." },
  { id:20, categoria:"normas", pregunta:"Se puede usar el telefono celular mientras se conduce?", opciones:["Si usando manos libres","Si en semaforos en rojo","Esta prohibido sostenerlo con la mano - se permite manos libres","Solo para llamadas cortas"], respuesta:0, explicacion:"Esta prohibido sostener el celular con la mano. Se permite el uso de sistemas manos libres." },
  { id:21, categoria:"manejo", pregunta:"Que es el punto ciego en un vehiculo?", opciones:["El area invisible por el capo","Las zonas que no cubren los espejos retrovisores","El area detras al estacionar","La zona debajo del vehiculo"], respuesta:1, explicacion:"El punto ciego es la zona que no puede verse a traves de los espejos. Se debe girar la cabeza antes de cambiar de carril." },
  { id:22, categoria:"manejo", pregunta:"Que se debe hacer cuando el vehiculo comienza a derrapar?", opciones:["Frenar fuertemente y girar en sentido contrario","Girar el volante en la direccion del derrape y soltar el acelerador suavemente","Acelerar para salir del derrape","Girar el volante en sentido contrario"], respuesta:1, explicacion:"Al derrapar se debe girar el volante en la direccion del derrape y soltar el acelerador gradualmente." },
  { id:23, categoria:"manejo", pregunta:"Cuando se deben encender las luces del vehiculo?", opciones:["Solo de noche","Media hora despues del atardecer","Desde el atardecer hasta el amanecer y cuando la visibilidad sea reducida","Solo en carreteras de noche"], respuesta:2, explicacion:"Las luces deben encenderse desde el atardecer hasta el amanecer y cuando las condiciones reducen la visibilidad." },
  { id:24, categoria:"manejo", pregunta:"Que se debe hacer al estacionar cuesta abajo cerca de la acera?", opciones:["Girar las ruedas hacia la izquierda","Girar las ruedas hacia la acera y usar el freno de mano","Dejar las ruedas rectas","No importa la posicion de las ruedas"], respuesta:1, explicacion:"Al estacionar cuesta abajo: girar las ruedas hacia la acera y siempre usar el freno de mano." },
  { id:25, categoria:"manejo", pregunta:"Que se debe verificar antes de realizar un cambio de carril?", opciones:["Solo los espejos laterales","Solo el espejo retrovisor central","Los espejos retrovisores y los puntos ciegos girando la cabeza","Solo encender el direccional"], respuesta:2, explicacion:"Antes de cambiar de carril: revisar espejos girar la cabeza para el punto ciego y activar el direccional." },
  { id:26, categoria:"manejo", pregunta:"Que es el aquaplaning o hidroplaneado?", opciones:["Cuando el vehiculo frena en terreno mojado","Cuando las ruedas pierden traccion sobre agua y el vehiculo se desliza sin control","El sonido de las ruedas en pavimento humedo","La perdida de potencia del motor en lluvia"], respuesta:1, explicacion:"El aquaplaning ocurre cuando se forma una capa de agua entre el neumatico y el pavimento perdiendo el control." },
  { id:27, categoria:"seguridad", pregunta:"A que edad pueden ir ninos sin silla especial en el asiento trasero?", opciones:["A partir de los 8 anos o 1.35 metros de altura","A partir de los 10 anos","A partir de los 12 anos","Siempre hasta los 5 anos con silla"], respuesta:0, explicacion:"En Chile los ninos menores de 8 anos y que midan menos de 1.35 metros deben usar silla de seguridad homologada." },
  { id:28, categoria:"seguridad", pregunta:"Cuando se deben usar las luces de emergencia (balizas)?", opciones:["Cuando el conductor esta apurado","Cuando el vehiculo esta detenido o circula muy lento representando peligro","En cualquier zona de obras","Solo cuando hay averia"], respuesta:1, explicacion:"Las balizas se usan cuando el vehiculo esta detenido en la calzada o circula a velocidad anormalmente baja." },
  { id:29, categoria:"seguridad", pregunta:"En un accidente con heridos cual es el primer paso correcto?", opciones:["Mover a los heridos a un lugar seguro","Llamar inmediatamente al 131","Senalizar el lugar y NO mover a los heridos salvo peligro inminente","Tomar fotografias para el seguro"], respuesta:2, explicacion:"Ante un accidente: senalizar el lugar NO mover heridos llamar al SAMU (131) y Carabineros (133)." },
  { id:30, categoria:"seguridad", pregunta:"Que documentos debe llevar siempre el conductor?", opciones:["Solo la licencia de conducir","Licencia y permiso de circulacion","Licencia permiso de circulacion revision tecnica y SOAP","Solo licencia y SOAP"], respuesta:2, explicacion:"El conductor debe llevar: Licencia de conducir Permiso de circulacion Revision tecnica y SOAP vigentes." },
  { id:31, categoria:"seguridad", pregunta:"Que significa conducir en estado de fatiga?", opciones:["Conducir con hambre","Conducir con sueno cansancio extremo o disminucion de reflejos","Conducir despues de hacer ejercicio","Conducir mas de 2 horas seguidas"], respuesta:1, explicacion:"La fatiga al volante reduce reflejos y concentracion. Se debe parar y descansar cada 2 horas en viajes largos." },
  { id:32, categoria:"seguridad", pregunta:"Cual es el sistema de seguridad mas eficaz para salvar vidas?", opciones:["El airbag","El ABS","El cinturon de seguridad","La carroceria reforzada"], respuesta:2, explicacion:"El cinturon de seguridad reduce en un 50% el riesgo de muerte en accidente frontal. El airbag complementa pero NO reemplaza al cinturon." },
  { id:33, categoria:"mecanica", pregunta:"Que indica el testigo de aceite en el tablero del vehiculo?", opciones:["Que el aceite esta caliente","Nivel o presion de aceite insuficiente - detener de inmediato","Que se debe cambiar el aceite pronto","Que el motor funciona correctamente"], respuesta:1, explicacion:"El testigo de aceite indica presion o nivel insuficiente. Continuar puede causar danos graves al motor." },
  { id:34, categoria:"mecanica", pregunta:"Cual es la presion correcta de los neumaticos?", opciones:["La misma para todos 30 PSI","La indicada por el fabricante en la etiqueta de la puerta del conductor","La maxima que indica el neumatico","Depende solo del clima"], respuesta:1, explicacion:"La presion correcta esta indicada por el fabricante y aparece en la etiqueta en el marco de la puerta del conductor." },
  { id:35, categoria:"mecanica", pregunta:"Que indica el testigo de temperatura del motor encendido?", opciones:["Que el motor esta frio","Motor sobrecalentado - detener el vehiculo de forma segura","Que se debe cambiar el refrigerante","Que el aire acondicionado esta encendido"], respuesta:1, explicacion:"El testigo de temperatura indica sobrecalentamiento. Se debe detener el vehiculo de forma segura y esperar a que se enfrie." },
  { id:36, categoria:"mecanica", pregunta:"Cada cuanto tiempo se recomienda revisar el nivel de aceite?", opciones:["Solo en el taller anualmente","Cada 10.000 km","Mensualmente o antes de viajes largos","Solo cuando aparece la luz de advertencia"], respuesta:2, explicacion:"Se recomienda revisar el nivel de aceite mensualmente o antes de viajes largos con el motor frio." },
  { id:37, categoria:"normas", pregunta:"Quien tiene preferencia en un paso peatonal senalizado?", opciones:["El vehiculo siempre tiene preferencia","El peaton que ya esta cruzando o a punto de cruzar","El vehiculo si viene a alta velocidad","Depende de quien llego primero"], respuesta:1, explicacion:"En los pasos peatonales senalizados el peaton tiene preferencia absoluta sobre los vehiculos." },
  { id:38, categoria:"normas", pregunta:"Esta permitido estacionar frente a una salida de emergencia?", opciones:["Si por periodos cortos","Si si se deja en marcha","No esta absolutamente prohibido","Solo de noche"], respuesta:2, explicacion:"Esta absolutamente prohibido estacionar frente a salidas de emergencia accesos de bomberos e hidrantes." },
  { id:39, categoria:"normas", pregunta:"Cuando puede un vehiculo particular usar el carril del bus-taxi?", opciones:["Nunca solo transporte publico","Para girar en la esquina proxima","Para vehiculos de emergencia","Los fines de semana"], respuesta:1, explicacion:"Los vehiculos particulares pueden usar la pista exclusiva solo para girar en la esquina inmediatamente siguiente." },
  { id:40, categoria:"normas", pregunta:"Que significa una luz de semaforo amarilla?", opciones:["Acelerar para cruzar antes que cambie a rojo","Detener el vehiculo si es posible de forma segura","Igual que la luz verde","Reducir velocidad a 30 km/h"], respuesta:1, explicacion:"La luz amarilla indica que el semaforo va a cambiar a rojo. Se debe detener si es seguro hacerlo." },
  { id:41, categoria:"normas", pregunta:"Al acercarse a una interseccion con semaforo en verde que se debe hacer?", opciones:["Acelerar para cruzar rapido","Mantener velocidad sin verificar","Reducir velocidad y verificar que otros vehiculos respetan su semaforo","Tocar el claxon para advertir"], respuesta:2, explicacion:"Aunque el semaforo este en verde siempre se debe tener precaucion al cruzar intersecciones." },
  { id:42, categoria:"normas", pregunta:"Conducir ebrio en Chile conlleva:", opciones:["Solo suspension de licencia por 1 ano","Multa economica unicamente","Suspension de licencia multa elevada y posiblemente prision","Solo se pierde la licencia si hay accidente"], respuesta:2, explicacion:"Conducir en estado de ebriedad conlleva: suspension de licencia multas elevadas y puede derivar en prision." },
  { id:43, categoria:"normas", pregunta:"Se puede adelantar en un cruce peatonal o interseccion?", opciones:["Si si no hay peatones","Solo en intersecciones sin semaforo","No esta prohibido adelantar en cruces peatonales e intersecciones","Solo de dia"], respuesta:2, explicacion:"Esta prohibido adelantar en cruces peatonales intersecciones tuneles y donde la visibilidad sea reducida." },
  { id:44, categoria:"seguridad", pregunta:"Cual es la distancia minima para colocar triangulos de emergencia?", opciones:["10 metros","30 metros por delante y por detras del vehiculo","50 metros por detras","100 metros"], respuesta:1, explicacion:"Los triangulos de advertencia deben colocarse a al menos 30 metros por delante y por detras del vehiculo averiado." },
  { id:45, categoria:"senales", pregunta:"Que color tienen las senales de turismo y lugares de interes en Chile?", opciones:["Azul","Verde","Cafe (marron)","Amarillo"], respuesta:2, explicacion:"Las senales de turismo y patrimonio cultural en Chile son de color cafe (marron) con letras blancas." },
  { id:46, categoria:"normas", pregunta:"Que se debe hacer cuando un vehiculo escolar se detiene con luces intermitentes?", opciones:["Adelantarlo rapidamente","Detenerse y esperar hasta que el vehiculo reanude la marcha","Reducir velocidad y continuar con precaucion","Tocar la bocina"], respuesta:1, explicacion:"Cuando un vehiculo escolar esta detenido con luces intermitentes se debe detener y esperar que los ninos suban o bajen." },
  { id:47, categoria:"manejo", pregunta:"Como se debe frenar en una bajada pronunciada con vehiculo manual?", opciones:["Frenar fuertemente con el freno de servicio","Usar el freno del motor (reducir marcha) y frenar suavemente de forma intermitente","Dejar el vehiculo en punto muerto","Usar solo el freno de mano"], respuesta:1, explicacion:"En bajadas pronunciadas reducir la marcha para usar el freno del motor y aplicar el freno de servicio suavemente." },
  { id:48, categoria:"normas", pregunta:"Que indica una linea amarilla continua en el borde de la calzada?", opciones:["Zona de estacionamiento permitido","Prohibicion de estacionar o detenerse","Velocidad reducida en ese sector","Carril de solo buses"], respuesta:1, explicacion:"Una linea amarilla continua en el borde de la calzada indica prohibicion de estacionar o detenerse." },
  { id:49, categoria:"seguridad", pregunta:"Cual es el efecto del cansancio extremo al conducir?", opciones:["Solo afecta levemente los reflejos","No afecta a conductores experimentados","Produce efectos similares a la ebriedad: microsuenos y perdida de reflejos","Solo es peligroso en carreteras"], respuesta:2, explicacion:"El cansancio extremo produce microsuenos lentitud de reflejos y perdida de concentracion comparable a conducir bajo el alcohol." },
  { id:50, categoria:"normas", pregunta:"Que se debe hacer al llegar a una rotonda?", opciones:["El que entra a la rotonda tiene preferencia","Ceder el paso a los vehiculos que ya circulan dentro","El vehiculo mas grande tiene preferencia","El que llega primero entra primero"], respuesta:1, explicacion:"Al entrar a una rotonda se debe ceder el paso a los vehiculos que ya circulan en su interior." },
  { id:51, categoria:"senales", pregunta:"Que color tienen las senales de advertencia de peligro en Chile?", opciones:["Azul con letras blancas","Amarillo con letras o simbolos negros","Verde con letras blancas","Rojo con letras blancas"], respuesta:1, explicacion:"Las senales de advertencia de peligro en Chile son de forma triangular y de color amarillo con letras o simbolos negros." },
  { id:52, categoria:"senales", pregunta:"Que indica una senal de ZONA DE ESCUELA en la carretera?", opciones:["Velocidad maxima 60 km/h en esa zona","Reducir la velocidad a 30 km/h y tener precaucion especial con ninos","Solo aplica en dias de semana","Ceder el paso a buses escolares"], respuesta:1, explicacion:"En zonas de escuela se debe reducir la velocidad a 30 km/h y extremar precauciones para proteger a los ninos que puedan cruzar." },
  { id:53, categoria:"senales", pregunta:"Que forma tiene una senal de ADVERTENCIA de peligro en Chile?", opciones:["Octagonal (8 lados)","Circular","Triangular con vertice apuntando hacia arriba","Rectangular"], respuesta:2, explicacion:"Las senales de advertencia de peligro en Chile tienen forma triangular con vertice apuntando hacia arriba y borde rojo." },
  { id:54, categoria:"senales", pregunta:"Que indica una senal de DOBLE CURVA con la primera hacia la derecha?", opciones:["Girar obligatoriamente a la derecha","Hay una doble curva peligrosa: primero a la derecha, luego a la izquierda","Velocidad maxima en curva","Paso prohibido en curva"], respuesta:1, explicacion:"Esta senal de advertencia indica que hay una doble curva peligrosa por delante: la primera hacia la derecha y la segunda hacia la izquierda." },
  { id:55, categoria:"senales", pregunta:"Que indica una senal rectangular verde con nombre de ciudad y distancia en km?", opciones:["Limite de velocidad en esa ciudad","Informacion de destino y distancia en carretera","Zona de peaje proximo","Desvio obligatorio"], respuesta:1, explicacion:"Las senales verdes rectangulares informan sobre destinos y las distancias en kilometros hasta ellos. Son senales informativas de ruta." },
  { id:56, categoria:"senales", pregunta:"Que indica una senal de CRUCE DE FERROCARRIL sin barrera?", opciones:["El tren siempre para antes del cruce","Precaucion: cruce de ferrocarril sin barrera - el conductor debe reducir velocidad y asegurarse que no viene un tren","Solo aplica de noche","Prohibido cruzar con tren en movimiento"], respuesta:1, explicacion:"En cruces de ferrocarril sin barrera el conductor DEBE reducir la velocidad, mirar en ambas direcciones y asegurarse de que no viene ningun tren antes de cruzar." },
  { id:57, categoria:"senales", pregunta:"Que significa una senalizacion horizontal en forma de rayas blancas transversales en la calzada?", opciones:["Zona de adelantamiento prohibido","Paso peatonal (cruce cebra)","Separacion de carriles","Zona de estacionamiento"], respuesta:1, explicacion:"Las rayas blancas transversales en la calzada forman un paso peatonal (cruce cebra) donde los peatones tienen preferencia de paso." },
  { id:58, categoria:"senales", pregunta:"Que indica una senal circular azul con una flecha blanca?", opciones:["Prohibicion de giro","Giro o circulacion obligatoria en la direccion indicada","Carril de solo buses","Velocidad minima"], respuesta:1, explicacion:"Las senales circulares azules son de obligacion. Una flecha blanca en su interior indica que es obligatorio seguir en la direccion indicada por la flecha." },
  { id:59, categoria:"normas", pregunta:"En Chile, los conductores novatos (menos de 2 anos de licencia) tienen tolerancia de alcohol de:", opciones:["0.3 g/L igual que todos","0.1 g/L","0.0 g/L - tolerancia cero absoluta","0.2 g/L"], respuesta:2, explicacion:"Los conductores con menos de 2 anos de experiencia tienen tolerancia CERO de alcohol (0.0 g/L). Si se detecta cualquier traza de alcohol, se aplican sanciones." },
  { id:60, categoria:"normas", pregunta:"Cual es la velocidad maxima permitida en zonas con senal de zona escolar?", opciones:["40 km/h","50 km/h","30 km/h","20 km/h"], respuesta:2, explicacion:"En zonas escolares debidamente senalizadas la velocidad maxima es de 30 km/h para proteger a los ninos." },
  { id:61, categoria:"normas", pregunta:"Que se debe hacer cuando el vehiculo de adelante frena de emergencia?", opciones:["Tocar la bocina y frenar fuerte","Aplicar el freno de forma firme y controlada manteniendo la distancia de seguridad","Esquivar por la derecha inmediatamente","Esquivar por el carril de buses"], respuesta:1, explicacion:"Ante una frenada de emergencia del vehiculo de adelante se debe frenar firme y controladamente. Si se mantenia una distancia de seguridad adecuada (2 seg) habra espacio suficiente para detenerse." },
  { id:62, categoria:"normas", pregunta:"Que es el SOAP y por que es obligatorio en Chile?", opciones:["Es un sistema de lavado de autos para revisiones tecncias","Seguro Obligatorio de Accidentes Personales que cubre a victimas de accidentes de transito","Seguro de danos al vehiculo propio","Sistema de Orden de Aparcamiento Publico"], respuesta:1, explicacion:"El SOAP (Seguro Obligatorio de Accidentes Personales) es un seguro que cubre a todas las victimas de accidentes de transito en Chile, ya sean conductores, pasajeros o peatones. Es de contratacion obligatoria." },
  { id:63, categoria:"normas", pregunta:"Cuantos anos de vigencia tiene la Licencia de Conducir Clase B en Chile (primer otorgamiento)?", opciones:["1 ano","2 anos","3 anos","5 anos"], respuesta:1, explicacion:"La primera Licencia B en Chile tiene una vigencia de 2 anos. A partir de la segunda renovacion la vigencia es de 5 anos." },
  { id:64, categoria:"normas", pregunta:"Esta permitido dar vuelta en U en cualquier parte de la calle?", opciones:["Si, siempre que no haya trafico","No, solo se permite donde haya espacio suficiente y no este prohibido por senalizacion","Si, en intersecciones con semaforo","Solo en zonas residenciales"], respuesta:1, explicacion:"La vuelta en U solo esta permitida donde no este prohibida por senalizacion y exista espacio suficiente para realizarla sin peligro para otros usuarios." },
  { id:65, categoria:"normas", pregunta:"Que se debe hacer al acercarse a un paso a nivel (cruce de ferrocarril) sin senales de advertencia?", opciones:["Cruzar rapidamente","Reducir la velocidad, detenerse si es necesario y verificar que no viene ningun tren","Solo mirar hacia la derecha","No hay obligacion especial"], respuesta:1, explicacion:"En todo paso a nivel se debe reducir la velocidad al aproximarse, y si es necesario detenerse para verificar visual y auditivamente que no viene ningun tren." },
  { id:66, categoria:"normas", pregunta:"Que es la Revision Tecnica Vehicular (RTV) y cada cuanto debe realizarse?", opciones:["Revision de emisiones, anualmente para vehiculos nuevos; cada 6 meses para vehiculos de mas de 5 anos","Revision del seguro, solo al vender el auto","Revision del kilometraje por el fabricante","Prueba de frenos en taller"], respuesta:0, explicacion:"La Revision Tecnica Vehicular (RTV) es una inspeccion obligatoria que verifica el estado mecanico, de seguridad y las emisiones del vehiculo. Los autos nuevos la hacen anualmente; los de mas de 5 anos, cada 6 meses." },
  { id:67, categoria:"normas", pregunta:"Cual es la distancia minima a la que se debe detener un vehiculo antes de un cruce peatonal?", opciones:["1 metro","2 metros","La linea de detencion o a una distancia prudente que no obstruya el paso de peatones","5 metros"], respuesta:2, explicacion:"El vehiculo debe detenerse en la linea de detencion o, si no la hay, a una distancia prudente del cruce que no obstruya ni ponga en riesgo a los peatones." },
  { id:68, categoria:"normas", pregunta:"Que debe hacer el conductor si circula en sentido contrario en una via de un solo sentido?", opciones:["Acelerar para salir rapidamente","Detenerse de forma segura, encender las balizas y dar marcha atras o girar para corregir el error","Tocar la bocina para avisar a los demas","Seguir circulando si no hay trafico"], respuesta:1, explicacion:"Si por error se ingresa a una via de sentido contrario se debe detener de inmediato de forma segura, encender las luces de emergencia y maniobrar para abandonar esa via correctamente." },
  { id:69, categoria:"normas", pregunta:"Puede un ciclista circular por la calzada de automoviles en Chile?", opciones:["No, solo por veredas","Si, cuando no haya ciclovias disponibles, por el borde derecho de la calzada","Solo en zonas rurales","Solo de noche"], respuesta:1, explicacion:"En Chile los ciclistas tienen derecho a circular por la calzada cuando no exista ciclovia disponible. Deben hacerlo por el borde derecho y tienen los mismos derechos que un vehiculo." },
  { id:70, categoria:"normas", pregunta:"Cual es la multa por no llevar el cinturon de seguridad en Chile?", opciones:["No hay multa, es solo una recomendacion","Es una infraccion grave con multa y acumulacion de puntos negativos en la licencia","Solo aplica en autopistas","La multa es solo para el conductor, no para los pasajeros"], respuesta:1, explicacion:"No usar el cinturon de seguridad es una infraccion grave en Chile que conlleva multa economica. Aplica tanto para el conductor como para todos los pasajeros." },
  { id:71, categoria:"normas", pregunta:"Que se entiende por ZONA ROJA en el sistema de semaforos de Chile?", opciones:["Solo para bomberos","Zona donde el semaforo esta desactivado","No existe este termino en semaforos chilenos; los semaforos son rojo, amarillo y verde","Zona de alta congestión de trafico"], respuesta:2, explicacion:"En la senalizacion semafórica chilena no existe el concepto de zona roja. Los semaforos tienen tres luces: verde (paso), amarillo (prepararse para detenerse) y rojo (detencion obligatoria)." },
  { id:72, categoria:"normas", pregunta:"Que es la infraccion de MANEJO TEMERARIO en Chile?", opciones:["Conducir a 5 km/h sobre el limite","Conducir de forma que pone en peligro evidente la seguridad propia y de los demas: exceso de velocidad grave, zigzagueo, etc.","Olvidar encender las luces de noche","Estacionar en zona amarilla"], respuesta:1, explicacion:"El manejo temerario es conducir de manera que representa un peligro evidente para la vida: exceso de velocidad extremo, competencias clandestinas (picadas), zigzagueo, etc. Tiene penas de carcel y suspension de licencia." },
  { id:73, categoria:"manejo", pregunta:"Al circular en autopista y se necesita cambiar de carril hacia la izquierda, que se debe hacer?", opciones:["Girar el volante bruscamente","Verificar espejos y punto ciego, activar el direccional izquierdo, esperar un espacio suficiente y cambiar gradualmente","Solo activar el direccional izquierdo","Acelerar y cambiar rapidamente"], respuesta:1, explicacion:"Para cambiar de carril en autopista: 1) Mirar espejo retrovisor, 2) Mirar espejo lateral izquierdo, 3) Revisar punto ciego girando la cabeza, 4) Activar el direccional izquierdo, 5) Cambiar gradualmente cuando haya espacio seguro." },
  { id:74, categoria:"manejo", pregunta:"En una curva pronunciada, que tecnica de frenado es la correcta?", opciones:["Frenar dentro de la curva a medida que se gira","Frenar ANTES de entrar a la curva, y acelerar suavemente al salir","Mantener velocidad constante en toda la curva","Frenar justo al inicio de la curva"], respuesta:1, explicacion:"La tecnica correcta es frenar ANTES de la curva, entrar con la velocidad adecuada y acelerar suavemente al inicio de la salida. Frenar en medio de una curva puede causar perdida de control del vehiculo." },
  { id:75, categoria:"manejo", pregunta:"Que indica el nivel minimo de banda de rodadura (dibujo) recomendado para los neumaticos?", opciones:["1.0 mm","1.6 mm es el minimo legal pero se recomienda cambiar a los 3 mm","5 mm","El dibujo no importa si el neumatico esta inflado correctamente"], respuesta:1, explicacion:"El minimo legal de profundidad del dibujo del neumatico en Chile es 1.6 mm, pero los expertos recomiendan cambiarlo al llegar a 3 mm para mantener una buena adherencia, especialmente en lluvia." },
  { id:76, categoria:"manejo", pregunta:"Que es el frenado ABS (Anti-lock Braking System)?", opciones:["Un sistema que frena automaticamente en emergencias sin accion del conductor","Un sistema que impide que las ruedas se bloqueen al frenar fuerte, permitiendo seguir dirigiendo el vehiculo","Un sistema de freno de mano automatico","Un freno solo para lluvia"], respuesta:1, explicacion:"El ABS impide que las ruedas se bloqueen al frenar de emergencia. Esto permite al conductor mantener el control de la direccion mientras frena, reduciendo el riesgo de derrapaje. Con ABS se debe presionar el freno firmemente sin soltar." },
  { id:77, categoria:"manejo", pregunta:"Como se debe conducir en condiciones de lluvia intensa?", opciones:["Igual que en seco, el auto moderno lo maneja","Reducir significativamente la velocidad, aumentar la distancia de seguimiento a 4 segundos y encender las luces","Solo encender las luces delanteras","Activar el modo sport del vehiculo"], respuesta:1, explicacion:"En lluvia intensa se debe: reducir la velocidad (el pavimento mojado aumenta la distancia de frenado), aumentar la distancia de seguimiento a 4 segundos, encender luces y evitar frenadas o giros bruscos." },
  { id:78, categoria:"manejo", pregunta:"Que se debe hacer si se revienta un neumatico mientras se conduce a alta velocidad?", opciones:["Frenar fuertemente de inmediato","Soltar el acelerador suavemente, mantener el volante firme y dejar que el vehiculo desacelere solo antes de frenar con suavidad","Girar el volante en sentido contrario","Cambiar de carril rapidamente"], respuesta:1, explicacion:"Ante un reventón: no frenar de golpe, soltar suavemente el acelerador, mantener el volante firme con ambas manos, dejar desacelerar al vehiculo y solo cuando la velocidad sea baja frenar suavemente. Activar las balizas y dirigirse al costado de la via." },
  { id:79, categoria:"manejo", pregunta:"Cuando se debe usar el freno de mano (freno de estacionamiento) ademas de al estacionar?", opciones:["Solo cuando el vehiculo esta detenido completamente","Para ayudar a frenar en bajadas","En pendientes mientras se espera en semaforo con vehiculo manual, para no retroceder","Para detener el vehiculo en emergencias en vez del freno de pie"], respuesta:2, explicacion:"En vehiculos manuales, al detenerse en un semaforo en pendiente, se usa el freno de mano para evitar retroceder al soltar el embrague. Tambien en estacionamientos en pendiente. NO debe usarse para frenar el vehiculo en movimiento (salvo emergencia extrema)." },
  { id:80, categoria:"manejo", pregunta:"Que distancia se recomienda tener con el volante al sentarse al volante?", opciones:["Lo mas cerca posible para tener mas control","Lo mas lejos posible para mayor comodidad","Los brazos deben quedar ligeramente flexionados al sostener el volante, espalda bien apoyada en el respaldo","No hay posicion correcta, depende de la comodidad"], respuesta:2, explicacion:"La posicion correcta al volante: brazos ligeramente flexionados al sujetar el volante a las posiciones 9 y 3, espalda totalmente apoyada en el respaldo, pies llegando comodamente a los pedales. Esto reduce la fatiga y permite mejor control." },
  { id:81, categoria:"seguridad", pregunta:"Que se debe hacer en caso de incendio del vehiculo mientras se conduce?", opciones:["Abrir las ventanas y acelerar para apagar el fuego","Detener el vehiculo de forma segura, apagar el motor, evacuar a todos los ocupantes y alejarse del vehiculo. Llamar a bomberos (132)","Seguir conduciendo hasta llegar a un taller","Intentar apagar el fuego con agua del radiador"], respuesta:1, explicacion:"En caso de incendio: detenerse de forma segura, apagar el motor (NO abrir el capo si hay humo por ahi), evacuar inmediatamente a todos, alejarse del vehiculo y llamar a Bomberos (132)." },
  { id:82, categoria:"seguridad", pregunta:"Que es un microsueno al volante y por que es peligroso?", opciones:["Un sueno breve de 8 horas que no afecta la conduccion","Una perdida involuntaria de consciencia de 1 a 30 segundos mientras se conduce, extremadamente peligrosa","Una tecnica de descanso para conductores de larga distancia","Solo ocurre de madrugada"], respuesta:1, explicacion:"Un microsueño es una perdida involuntaria de consciencia de entre 1 y 30 segundos. A 120 km/h, en 4 segundos el vehiculo recorre 133 metros sin control. Es una de las principales causas de accidentes fatales en carretera." },
  { id:83, categoria:"seguridad", pregunta:"Cuales son los numeros de emergencia en Chile que todo conductor debe conocer?", opciones:["Solo el 911","131 (SAMU), 132 (Bomberos), 133 (Carabineros) y 134 (PDI)","Solo el 133 de Carabineros","911 y 100"], respuesta:1, explicacion:"Los numeros de emergencia en Chile son: 131 SAMU (emergencias medicas), 132 Bomberos (incendios), 133 Carabineros (seguridad publica) y 134 PDI. Todo conductor debe memorizarlos." },
  { id:84, categoria:"seguridad", pregunta:"Que es la zona de deformacion programada de un vehiculo y para que sirve?", opciones:["Una zona del interior del auto que se puede personalizar","Zonas del chasis del vehiculo disenadas para deformarse y absorber la energia del impacto en un choque, protegiendo a los ocupantes","Un defecto de fabricacion","El area del maletero del vehiculo"], respuesta:1, explicacion:"Las zonas de deformacion programada son estructuras del chasis que se deforman controladamente en un accidente, absorbiendo la energia del choque y protegiéndo al habitaculo donde van los ocupantes." },
  { id:85, categoria:"seguridad", pregunta:"Esta permitido el uso de auriculares o audfonos al conducir en Chile?", opciones:["Si, para musica","Si, pero solo con un auricular para mantener atencion al entorno","No, el uso de audifonos o auriculares que impidan oir el entorno esta prohibido mientras se conduce","Solo en carreteras"], respuesta:2, explicacion:"En Chile esta prohibido conducir con audifonos o auriculares que impidan escuchar el sonido del entorno (sirenas, bocinas, etc.). Reducen la capacidad de reaccion y la percepcion del peligro." },
  { id:86, categoria:"seguridad", pregunta:"Que se entiende por distancia de frenado y por que aumenta con la velocidad?", opciones:["La distancia que recorre el auto desde que el conductor ve el peligro hasta que decide frenar","La distancia que recorre el auto desde que el conductor aplica el freno hasta que el vehiculo se detiene completamente","La distancia entre el vehiculo y el de adelante","La longitud del pedal de freno"], respuesta:1, explicacion:"La distancia de frenado es la que recorre el vehiculo desde que el conductor pisa el freno hasta que se detiene. Aumenta con la velocidad de forma cuadratica: al doblar la velocidad la distancia de frenado se cuadruplica. A esto se suma la distancia de reaccion." },
  { id:87, categoria:"seguridad", pregunta:"Que se debe hacer si un nino no usa correctamente el cinturon de seguridad en el asiento trasero?", opciones:["No es necesario corregirlo si el nino se queja del cinturon","El conductor debe detener el vehiculo en un lugar seguro y asegurarse de que el nino quede correctamente asegurado antes de continuar","Solo el copiloto debe corregirlo","Los ninos no necesitan cinturon en el asiento trasero"], respuesta:1, explicacion:"Es responsabilidad del conductor asegurarse de que TODOS los ocupantes, especialmente los ninos, viajen correctamente asegurados. Debe detenerse en un lugar seguro para corregir la situacion antes de continuar." },
  { id:88, categoria:"seguridad", pregunta:"Que equipamiento de seguridad debe llevar un vehiculo particular en Chile para una emergencia?", opciones:["Solo un extintor","Triangulos de advertencia (minimo 2), kit de primeros auxilios, extintor y chaleco reflectante","Solo el gato hidraulico y neumatico de repuesto","Solo el extintor y el neumatico de repuesto"], respuesta:1, explicacion:"Para una emergencia en carretera se recomienda llevar: triangulos de advertencia (minimo 2), kit de primeros auxilios, extintor y chaleco reflectante de alta visibilidad. En Chile algunos de estos son obligatorios segun el tipo de vehiculo." },
  { id:89, categoria:"mecanica", pregunta:"Que indica el testigo de bateria encendido en el tablero?", opciones:["Que la bateria esta completamente cargada","Que el sistema de carga (alternador) no esta funcionando correctamente y la bateria se esta descargando","Que se debe cambiar la bateria pronto","Que las luces estan encendidas"], respuesta:1, explicacion:"El testigo de bateria indica que el alternador no esta cargando la bateria. Si se ignora, la bateria se agotara y el vehiculo se apagara. Se debe ir a un taller lo antes posible." },
  { id:90, categoria:"mecanica", pregunta:"Que funcion tiene el liquido de frenos en un vehiculo?", opciones:["Lubrificar los frenos para que no se desgasten","Transmitir la presion del pedal de freno a las pastillas y zapatas que detienen las ruedas","Refrigerar el motor durante el frenado","Limpiar los discos de freno"], respuesta:1, explicacion:"El liquido de frenos (hidraulico) transmite la presion que se aplica al pedal hacia los mecanismos de frenado (pastillas y zapatas) en cada rueda. Es hidroscopico y debe cambiarse cada 2 anos o segun el fabricante." },
  { id:91, categoria:"mecanica", pregunta:"Que pasa si el nivel de refrigerante (agua) del motor esta bajo?", opciones:["El motor consume mas combustible","El motor puede sobrecalentarse y sufrir danos graves o irreparables","Las luces del tablero se apagan","El auto consume mas aceite"], respuesta:1, explicacion:"El refrigerante mantiene la temperatura del motor dentro del rango optimo. Si el nivel es bajo el motor puede sobrecalentarse, lo que puede causar danos irreparables como deformacion de la culata o falla del motor." },
  { id:92, categoria:"mecanica", pregunta:"Con que frecuencia se recomienda cambiar las escobillas (plumillas) del limpiaparabrisas?", opciones:["Solo cuando dejan de funcionar por completo","Cada 6 a 12 meses o cuando se noten rayas o chirridos al limpiar","Cada 5 anos","No necesitan cambio, son permanentes"], respuesta:1, explicacion:"Las escobillas del limpiaparabrisas se deterioran con el tiempo y la exposicion al sol. Se recomienda cambiarlas cada 6 a 12 meses para garantizar una visibilidad optima en lluvia, que es critica para la seguridad." },
  { id:93, categoria:"mecanica", pregunta:"Que indica un ruido chirrante al frenar?", opciones:["Es normal en vehiculos modernos","Las pastillas de freno estan desgastadas y necesitan reemplazo urgente","Solo indica que los frenos estan frios","El vehiculo necesita gasolina"], respuesta:1, explicacion:"Un ruido chirrante al frenar generalmente indica que las pastillas de freno estan desgastadas. Muchas pastillas tienen indicadores metalicos que generan este sonido al llegar al limite de desgaste. Deben reemplazarse de inmediato." },
  { id:94, categoria:"mecanica", pregunta:"Que funcion cumple el alternador en el vehiculo?", opciones:["Transforma la energia electrica en mecanica para mover el auto","Genera electricidad para cargar la bateria y alimentar los sistemas electricos del vehiculo mientras el motor esta en marcha","Controla la temperatura del motor","Filtra el combustible"], respuesta:1, explicacion:"El alternador es un generador electrico accionado por el motor que produce la electricidad necesaria para recargar la bateria y alimentar todos los sistemas electricos del vehiculo cuando el motor esta funcionando." },
  { id:95, categoria:"normas", pregunta:"Que se debe hacer al acercarse a una interseccion con semaforo apagado (sin luz)?", opciones:["El que llega primero cruza","Tratarlo como una senalizacion de PARE: detenerse y ceder el paso segun las reglas de prioridad","Seguir a velocidad normal","Tocar la bocina y cruzar"], respuesta:1, explicacion:"Cuando un semaforo esta apagado o averiado, la interseccion debe tratarse como si hubiera una senalizacion de PARE para todos los accesos: todos deben detenerse y ceder el paso segun las reglas de prioridad." },
  { id:96, categoria:"normas", pregunta:"Esta permitido estacionar en una esquina (a menos de 10 metros de ella)?", opciones:["Si, si se hace rapido","Si, en zona residencial","No, esta prohibido estacionar a menos de 10 metros de una esquina o bocacalle para garantizar la visibilidad","Solo si hay espacio suficiente"], respuesta:2, explicacion:"Esta prohibido estacionar a menos de 10 metros de una esquina o bocacalle. Hacerlo reduce la visibilidad de conductores y peatones, aumentando el riesgo de accidentes." },
  { id:97, categoria:"normas", pregunta:"Que se debe hacer si el vehiculo de adelante se detiene de emergencia y el conductor de atras no puede frenar a tiempo?", opciones:["Atropellar al vehiculo de adelante","Si no es posible frenar a tiempo, virar hacia donde haya menor riesgo de dano o lesiones","Cerrar los ojos","Acelerar para minimizar el impacto"], respuesta:1, explicacion:"Si una frenada de emergencia es inevitable, se debe valorar rapidamente si es mas seguro virar (hacia donde haya menor riesgo) o seguir frenando. Esto refuerza la importancia de mantener siempre la distancia de seguimiento adecuada." },
  { id:98, categoria:"normas", pregunta:"Que es la VIA PREFERENCIAL y que derechos otorga?", opciones:["Una autopista de alta velocidad","Una via donde el trafico que circula por ella tiene prioridad de paso sobre los vehiculos que se incorporan desde vias secundarias","Una pista exclusiva para buses","Una zona de velocidad reducida"], respuesta:1, explicacion:"La via preferencial es aquella que tiene prioridad de paso sobre las vias que la intersectan. Esta marcada con senalizacion especifica. Los vehiculos que vienen de vias secundarias deben ceder el paso." },
  { id:99, categoria:"normas", pregunta:"Cual de estos factores NO reduce la capacidad para conducir de forma segura?", opciones:["Consumo de alcohol","Tomar medicamentos que producen sueno","Escuchar musica a bajo volumen con el sistema de audio del vehiculo","Consumo de cannabis (marihuana)"], respuesta:2, explicacion:"La musica a bajo volumen con el sistema de audio del vehiculo no afecta significativamente la capacidad de conduccion. El alcohol, los medicamentos sedantes y el cannabis son sustancias que impiden la conduccion segura." },
  { id:100, categoria:"normas", pregunta:"En Chile, la Ley de Transito establece que en una via de doble sentido, adelantar por la derecha esta:", opciones:["Permitido siempre que haya espacio","Permitido solo en autopista","Prohibido, salvo que el vehiculo de adelante haya senalado que va a girar a la izquierda y haya espacio suficiente","Siempre prohibido sin excepciones"], respuesta:2, explicacion:"En Chile adelantar por la derecha esta generalmente prohibido. La excepcion es cuando el vehiculo de adelante ha indicado claramente que va a girar a la izquierda y existe espacio suficiente para pasar por su derecha de forma segura." },
  { id:101, categoria:"senales", pregunta:"Que forma tiene una senal de PROHIBICION en Chile?", opciones:["Triangular con borde rojo","Cuadrada azul","Circular con borde rojo y fondo blanco","Rectangular verde"], respuesta:2, explicacion:"Las senales de prohibicion en Chile son circulares con borde rojo y fondo blanco. La señal de PARE es la excepcion, ya que es octagonal roja." },
  { id:102, categoria:"senales", pregunta:"Una senal de trafico de fondo AZUL con simbolo blanco indica:", opciones:["Peligro proximo","Prohibicion","Obligacion o informacion de servicio","Velocidad maxima"], respuesta:2, explicacion:"Las senales de fondo azul con simbolo blanco son senales de obligacion (como sentido obligatorio, uso de cadenas) o informativas de servicios." },
  { id:103, categoria:"senales", pregunta:"Que indica una senal con el simbolo de un telefono sobre fondo azul?", opciones:["Zona sin cobertura celular","Telefono de emergencia disponible en esa zona de carretera","Prohibido usar el celular","Cabina telefonica a 100 metros"], respuesta:1, explicacion:"Esta senal informativa indica que hay un telefono de emergencia disponible en esa seccion de carretera, util en caso de averia o accidente." },
  { id:104, categoria:"senales", pregunta:"Que indica una senal de CURVA PELIGROSA A LA IZQUIERDA?", opciones:["Gira obligatoriamente a la izquierda","Hay una curva pronunciada a la izquierda que exige reducir la velocidad","Esta prohibido girar a la izquierda","Solo aplica de noche"], respuesta:1, explicacion:"Es una senal de advertencia que indica que hay una curva cerrada hacia la izquierda. El conductor debe reducir la velocidad antes de entrar a la curva." },
  { id:105, categoria:"senales", pregunta:"Que indica una senal triangular con un automovil y lineas de derrape?", opciones:["Zona de estacionamiento","Advertencia de superficie resbaladiza o calzada deslizante","Prohibido frenar","Zona de pruebas vehiculares"], respuesta:1, explicacion:"Esta senal de advertencia indica calzada deslizante o superficie con poca adherencia. Se debe reducir la velocidad y evitar frenadas o aceleraciones bruscas." },
  { id:106, categoria:"senales", pregunta:"Que indica una senal con un hombre trabajando (obrero con pala)?", opciones:["Prohibido el paso permanente","Zona de obras: reducir velocidad y extremar precauciones","Desvio obligatorio a 500 metros","Peaje proximo"], respuesta:1, explicacion:"La senal de obras o trabajos en la via indica que hay personal trabajando en la calzada. Se debe reducir la velocidad, respetar la senalizacion provisional y extremar precauciones." },
  { id:107, categoria:"senales", pregunta:"Que indica una senal de PEATON en una triangular de advertencia?", opciones:["Prohibido el paso de peatones","Zona de cruce de peatones frecuente: precaucion","Solo aplica en zonas comerciales","Peatones en carretera en sentido contrario"], respuesta:1, explicacion:"La senal triangular de advertencia con un peaton indica que es una zona de cruce frecuente de peatones y que el conductor debe extremar la precaucion." },
  { id:108, categoria:"senales", pregunta:"Que significa la senal de NO ENTRAR (circulo rojo con barra blanca horizontal)?", opciones:["Velocidad maxima","Prohibido el acceso a esa via en esa direccion (contramano)","Prohibido estacionar","Fin de zona de restriccion"], respuesta:1, explicacion:"La senal de NO ENTRAR prohíbe el acceso a la via en ese sentido. Generalmente se coloca en la salida de vias de un solo sentido para evitar el ingreso en contramano." },
  { id:109, categoria:"senales", pregunta:"Que indica una senal de ZONA DE ADELANTAMIENTO PROHIBIDO (linea continua + senal)?", opciones:["Se puede adelantar solo a bicicletas","Prohibido adelantar en esa seccion de via","Solo aplica para camiones","Prohibido reducir la velocidad"], respuesta:1, explicacion:"La combinacion de senal de adelantamiento prohibido mas linea continua en el eje de la calzada prohibe totalmente adelantar en esa seccion. Incumplirlo es una infraccion grave." },
  { id:110, categoria:"senales", pregunta:"Una senal de ALTURA MAXIMA con el numero 3.5 indica:", opciones:["Velocidad maxima de 3.5 km/h","Los vehiculos que superen 3.5 metros de altura no pueden pasar por ese lugar","Distancia de 3.5 metros al obstaculo","Pendiente del 3.5%"], respuesta:1, explicacion:"La senal de altura maxima indica que los vehiculos con una altura superior a la indicada (en este caso 3.5 metros) no pueden ingresar a ese paso, puente o tunel." },
  { id:111, categoria:"normas", pregunta:"Que se entiende por CONDUCCION DISTRAIDA?", opciones:["Conducir a baja velocidad","Conducir mientras se realizan actividades que desvian la atencion de la tarea de conducir (celular, comer, etc.)","Conducir de noche sin experiencia","Conducir con musica muy fuerte"], respuesta:1, explicacion:"La conduccion distraida es una de las principales causas de accidentes. Incluye usar el celular, comer, beber, cambiar la radio, hablar con pasajeros o cualquier actividad que desvie la atencion de la via." },
  { id:112, categoria:"normas", pregunta:"En Chile, a partir de que ano de fabricacion los autos deben tener airbag?", opciones:["Todos los autos fabricados desde 1990","Depende del fabricante, no hay obligacion legal en Chile","Todos los autos nuevos vendidos en Chile desde 2014 deben llevar airbag de conductor y copiloto","Solo los autos de lujo"], respuesta:2, explicacion:"Desde el ano 2014 en Chile es obligatorio que todos los autos nuevos que se vendan cuenten con airbag frontal para conductor y copiloto como equipamiento minimo de seguridad." },
  { id:113, categoria:"normas", pregunta:"Cual es la velocidad maxima permitida en calles con senal de zona 30 (zona residencial)?", opciones:["40 km/h","50 km/h","30 km/h","20 km/h"], respuesta:2, explicacion:"En zonas residenciales con senalizacion de Zona 30 la velocidad maxima es de 30 km/h. Estas zonas priorizan la seguridad de peatones y ciclistas sobre la velocidad de los vehiculos." },
  { id:114, categoria:"normas", pregunta:"Puede un conductor estacionar bloqueando la entrada de un garage privado?", opciones:["Si, por periodos cortos de hasta 5 minutos","Si, si deja las balizas encendidas","No, esta completamente prohibido bloquear entradas de garages o cocheras","Solo de noche"], respuesta:2, explicacion:"Esta absolutamente prohibido estacionar bloqueando entradas de garages o cocheras privados. El propietario del garage tiene derecho a solicitar el retiro del vehiculo y puede llamar a Carabineros." },
  { id:115, categoria:"normas", pregunta:"Que debe hacer el conductor si ve que un peaton anciano o con discapacidad esta cruzando?", opciones:["Acelerar para cruzar antes que el peaton","Tocar la bocina para que cruce mas rapido","Detener el vehiculo y esperar a que el peaton cruce completamente de forma segura","Seguir si hay mas de un carril"], respuesta:3, explicacion:"El conductor debe detenerse y esperar pacientemente a que el peaton, especialmente si es anciano, nino o persona con discapacidad, cruce completamente y de forma segura. Los peatones vulnerables merecen especial consideracion." },
  { id:116, categoria:"normas", pregunta:"Que son los PUNTOS EN LICENCIA en Chile y como afectan al conductor?", opciones:["Son puntos positivos que se acumulan por buen comportamiento","Sistema en el que las infracciones generan cargos (puntos negativos) y acumular demasiados puede resultar en suspension de la licencia","Son descuentos en el permiso de circulacion","Son puntos de bonificacion en el SOAP"], respuesta:1, explicacion:"El sistema de puntos en la licencia de conducir establece que las infracciones se traducen en puntos de demerito. Al acumular cierta cantidad de puntos en un periodo determinado, se puede suspender o cancelar la licencia de conducir." },
  { id:117, categoria:"normas", pregunta:"Cual es el procedimiento correcto al ser detenido por Carabineros en un control de transito?", opciones:["Salir rapidamente del vehiculo y acercarse al carabinero","Mantener la calma, detenerse de forma segura, encender las balizas y esperar instrucciones del funcionario en el interior del vehiculo","Acelerar y seguir si se va con prisa","Discutir si se cree que la detencion es injusta"], respuesta:1, explicacion:"Al ser detenido por Carabineros: detenerse en un lugar seguro, encender las balizas, permanecer en el vehiculo con las manos visibles y esperar instrucciones del funcionario. Mantener la calma y ser respetuoso." },
  { id:118, categoria:"normas", pregunta:"En Chile esta permitido conducir vehículos con vidrios polarizados?", opciones:["Si, sin restricciones en todos los vidrios","Si, pero la luna delantera y los vidrios laterales delanteros deben tener una transmision luminica minima del 70%","Solo en autos de lujo","No esta permitido en ningun vidrio"], respuesta:1, explicacion:"En Chile la ley permite vidrios polarizados, pero el parabrisas y los vidrios laterales del conductor y copiloto deben transmitir al menos el 70% de la luz, para garantizar la visibilidad del conductor." },
  { id:119, categoria:"normas", pregunta:"Que deben hacer los conductores cuando un vehiculo de emergencia activa su sirena por detras?", opciones:["Acelerar para no obstruir","Mantener velocidad y dejar que el vehiculo de emergencia se adelante","Reducir velocidad, desplazarse a la derecha y si es necesario detenerse para abrir paso","Frenar de golpe"], respuesta:2, explicacion:"Cuando se aproxima un vehiculo de emergencia con sirena y luz de advertencia, todos los conductores deben reducir la velocidad, desplazarse al costado derecho de la via y detenerse si es necesario para abrir un corredor de emergencia." },
  { id:120, categoria:"normas", pregunta:"Esta permitido llevar animales dentro del vehiculo sin restricciones?", opciones:["Si, siempre que quepan en el auto","No, los animales deben ir asegurados en transportines o con arneses especiales para no distraer al conductor","Solo en el maletero","Solo perros pequenos en el asiento trasero"], respuesta:1, explicacion:"Los animales deben ir asegurados con transportines o arneses homologados. Un animal suelto en el vehiculo puede distraer al conductor y convertirse en un proyectil peligroso en caso de frenada brusca o accidente." },
  { id:121, categoria:"normas", pregunta:"Que significa la expresion TIEMPO DE REACCION en la conduccion?", opciones:["El tiempo que demora el vehiculo en frenar completamente","El tiempo que transcurre entre que el conductor percibe un peligro y comienza a accionar el freno","La velocidad de respuesta del ABS","El tiempo que dura encendida la luz del semaforo amarillo"], respuesta:1, explicacion:"El tiempo de reaccion es el lapso entre que el conductor percibe el peligro y comienza a frenar. A 50 km/h el vehiculo recorre unos 14 metros solo en ese tiempo (aproximadamente 1 segundo). A mayor velocidad, mayor distancia recorrida antes de frenar." },
  { id:122, categoria:"normas", pregunta:"Cuantas horas consecutivas puede conducir un conductor de bus o camion en Chile?", opciones:["Sin limite si el conductor se siente bien","Maximo 5 horas continuas, luego debe descansar al menos 30 minutos","Maximo 8 horas continuas","Maximo 2 horas continuas"], respuesta:1, explicacion:"La normativa chilena establece que los conductores profesionales (buses, camiones) no pueden conducir mas de 5 horas consecutivas sin tomar un descanso de al menos 30 minutos. Estas normas buscan prevenir accidentes por fatiga." },
  { id:123, categoria:"normas", pregunta:"Que se debe hacer cuando se produce una averia y el vehiculo queda detenido en la autopista?", opciones:["Permanecer en el vehiculo y esperar ayuda","Salir del vehiculo, alejarse por la berma, colocar los triangulos de emergencia y llamar a ayuda en carretera","Intentar reparar el vehiculo en la pista","Hacer senas a otros conductores desde la pista"], respuesta:1, explicacion:"Ante una averia en autopista: 1) Llevar el vehiculo a la berma (si es posible), 2) Encender las balizas, 3) Salir del vehiculo y alejarse de la pista por la berma, 4) Colocar triangulos a 30 metros adelante y atras, 5) Llamar al servicio de asistencia o Carabineros." },
  { id:124, categoria:"normas", pregunta:"Que se entiende por PICADA o CARRERA CLANDESTINA y cuales son sus consecuencias legales en Chile?", opciones:["Una carrera automovilistica en circuito cerrado autorizado","Una competencia de velocidad no autorizada en la via publica, sancionada con prision, multas y cancelacion de licencia","Una exhibicion de autos en una feria","Una prueba de aceleracion en pistas autorizadas"], respuesta:1, explicacion:"Las picadas o carreras clandestinas en la via publica son ilegales en Chile. Se sancionan con penas de prision (cumplidas efectivamente), multas millonarias y cancelacion de la licencia de conducir. Son una de las principales causas de muertes en carretera." },
  { id:125, categoria:"normas", pregunta:"En que situacion el conductor puede usar la bocina (claxon) legalmente?", opciones:["Para avisar a peatones que molestan","Para expresar enojo con otro conductor","Para advertir de peligro inminente o como senal de presencia en curvas sin visibilidad en carretera","En cualquier momento que el conductor lo desee"], respuesta:2, explicacion:"La bocina debe usarse SOLO para advertir de peligro inminente o como senal acustica de presencia en curvas de montana sin visibilidad. Su uso abusivo e innecesario es una infraccion y genera contaminacion acustica." },
  { id:126, categoria:"manejo", pregunta:"Que es el efecto FADING de los frenos y como se produce?", opciones:["Cuando los frenos se mojan y dejan de funcionar","Perdida de eficacia de los frenos por sobrecalentamiento, generalmente por uso excesivo en bajadas largas","Cuando el liquido de frenos se acaba","Un defecto de fabrica en los frenos"], respuesta:1, explicacion:"El fading es la perdida de potencia de frenado por sobrecalentamiento de los frenos, causado por frenar repetidamente en bajadas largas. Para evitarlo se debe usar el freno del motor (reducir marcha) y frenar de forma intermitente, no continua." },
  { id:127, categoria:"manejo", pregunta:"Cual es la posicion correcta de las manos en el volante segun las recomendaciones actuales?", opciones:["12 y 6 (arriba y abajo)","10 y 2 (como el reloj)","9 y 3 (izquierda y derecha)","Solo con una mano a las 12"], respuesta:2, explicacion:"La recomendacion actual es sostener el volante en la posicion 9 y 3 (como si fuera un reloj). Esta posicion permite mayor control, menor fatiga y es mas segura en caso de activarse el airbag (en 10 y 2 los brazos pueden golpear la cara)." },
  { id:128, categoria:"manejo", pregunta:"Como se debe estacionar correctamente en una pendiente ascendente SIN acera?", opciones:["Girar las ruedas hacia la izquierda (hacia el centro de la calzada) y aplicar el freno de mano","Girar las ruedas hacia la derecha y aplicar el freno de mano","Dejar las ruedas rectas","No se puede estacionar en pendiente ascendente"], respuesta:0, explicacion:"En pendiente ascendente sin acera: girar las ruedas hacia la IZQUIERDA (hacia el centro de la calzada). Si el vehiculo cede, la rueda quedara apoyada en el borde de la calzada y no rodara hacia el trafico. Siempre aplicar el freno de mano." },
  { id:129, categoria:"manejo", pregunta:"Que es el subviraje (understeer) en un vehiculo?", opciones:["Cuando el vehiculo gira mas de lo esperado","Cuando el vehiculo no gira lo suficiente y tiende a irse recto aunque el conductor gire el volante","Un defecto del sistema de suspension","Un tipo de frenado especial"], respuesta:1, explicacion:"El subviraje ocurre cuando el vehiculo no sigue la trayectoria de giro del volante y tiende a irse hacia adelante. Es comun en autos de traccion delantera al entrar rapido a una curva. Se corrige reduciendo la velocidad y sin girar mas el volante." },
  { id:130, categoria:"manejo", pregunta:"Cual es la tecnica correcta para incorporarse a una autopista desde una via de aceleracion?", opciones:["Detenerse al final de la via de aceleracion y esperar un espacio","Entrar directamente a la pista sin mirar","Usar la via de aceleracion para igualar la velocidad con el trafico de la autopista y luego fusionarse suavemente cuando haya un espacio","Encender las balizas y esperar que alguien le ceda el paso"], respuesta:2, explicacion:"La via de aceleracion existe precisamente para que el conductor pueda alcanzar la velocidad del trafico de la autopista antes de incorporarse. Se debe usar todo su largo, mirar los espejos, activar el direccional y entrar suavemente al flujo de trafico." },
  { id:131, categoria:"manejo", pregunta:"Que es el punto muerto en un vehiculo de transmision manual?", opciones:["Cuando el motor se apaga","La posicion del cambio de velocidades en la que ningun engranaje esta acoplado y el motor no mueve las ruedas","El freno de mano","Cuando el vehiculo esta en reversa"], respuesta:1, explicacion:"El punto muerto (N) es la posicion del cambio de marchas donde ninguna velocidad esta engranada. El motor gira libremente sin mover las ruedas. No se debe bajar en punto muerto porque se pierde el freno del motor y control del vehiculo." },
  { id:132, categoria:"manejo", pregunta:"Como se debe realizar correctamente el giro a la derecha en una interseccion?", opciones:["A alta velocidad para no interferir con el trafico","Reduciendo velocidad, posicionandose en el carril derecho, verificando peatones y ciclistas, y girando manteniendo el carril derecho","Desde el carril izquierdo para mayor vision","Girando bruscamente sin senalizar"], respuesta:1, explicacion:"Para girar a la derecha: reducir velocidad, activar el direccional con anticipacion, posicionarse en el carril derecho, ceder el paso a peatones y ciclistas que crucen, y girar manteniendose en el carril derecho de la nueva via." },
  { id:133, categoria:"manejo", pregunta:"Que es el SOBREVIRAJE (oversteer) y como se corrige?", opciones:["Cuando el vehiculo no gira lo suficiente","Cuando la parte trasera del vehiculo se desliza hacia afuera de la curva. Se corrige girando el volante en la misma direccion del deslizamiento (derrape controlado)","Un tipo de suspension deportiva","Cuando el volante vibra en curva"], respuesta:1, explicacion:"El sobreviraje es cuando la parte trasera del vehiculo se va hacia afuera de la curva (derrape). Es tipico en autos de traccion trasera. Se corrige girando el volante HACIA donde va la parte trasera (contra-volantear) y soltando suavemente el acelerador." },
  { id:134, categoria:"manejo", pregunta:"Que se debe hacer cuando se conduce detras de un camion grande en autopista?", opciones:["Circular muy cerca para aprovechar el efecto aerodinamico","Adelantar siempre que sea posible","Mantener una distancia de seguimiento mayor a la normal ya que bloquea la visibilidad, y tener precaucion con viento lateral al adelantar","No hay diferencia con seguir a un auto pequeño"], respuesta:2, explicacion:"Detras de un camion grande: mantener mayor distancia (menor visibilidad de la via), estar atentos a objetos que puedan caer, y al adelantar tener precaucion con el viento lateral que puede desestabilizar el vehiculo." },
  { id:135, categoria:"manejo", pregunta:"Que es el FENOMENO DEL TUNEL en conduccion nocturna de largo recorrido?", opciones:["El efecto visual dentro de un tunel","La tendencia del conductor fatigado a reducir involuntariamente la amplitud de su vision y fijarse solo en un punto del camino","Un tipo de iluminacion vial","La perdida de potencia del motor de noche"], respuesta:1, explicacion:"El fenomeno del tunel es un sintoma de fatiga al volante: el conductor involuntariamente reduce su campo visual y se fija en un solo punto, dejando de percibir informacion periferica importante. Es una senal de alarma de que hay que parar a descansar." },
  { id:136, categoria:"seguridad", pregunta:"Que es la VISION PERIFERICA y por que es importante al conducir?", opciones:["La capacidad de ver muy lejos en linea recta","La capacidad de percibir movimiento y objetos fuera del centro del campo visual. Es clave para detectar peatones y vehiculos que cruzan","La vision nocturna","La capacidad de ver dentro de los espejos"], respuesta:1, explicacion:"La vision periferica es la capacidad de ver lo que ocurre a los lados sin mover los ojos. Permite detectar peatones, ciclistas y vehiculos que se aproximan desde los laterales. La fatiga, el alcohol y la velocidad excesiva la reducen considerablemente." },
  { id:137, categoria:"seguridad", pregunta:"Por que se debe prestar especial atencion a los puntos ciegos de los camiones al circular junto a ellos?", opciones:["Los camiones siempre tienen preferencia de paso","Los camiones tienen zonas ciegas mucho mas amplias que los autos, especialmente por los laterales y detras, donde el conductor del camion no puede verlos","Los camiones frena de forma diferente","Solo aplica en carreteras"], respuesta:1, explicacion:"Los camiones tienen angulos muertos (puntos ciegos) muy amplios: por delante del capo, a los laterales y detras. Si un auto queda en estas zonas el conductor del camion simplemente no puede verlo. La regla es: si no puedes ver los espejos del camionero, el tampoco te ve a ti." },
  { id:138, categoria:"seguridad", pregunta:"Que se entiende por ACCIDENTE IN ITINERE en Chile?", opciones:["Un accidente causado por falla mecanica","Un accidente de transito que ocurre en el trayecto desde el domicilio al trabajo o viceversa, cubierto por la seguridad laboral","Un accidente en zona de obras","Un accidente de transporte de carga"], respuesta:1, explicacion:"El accidente de transito in itinere es el que ocurre durante el trayecto normal entre el hogar y el lugar de trabajo (o viceversa). En Chile es cubierto como accidente laboral por la ley de accidentes del trabajo, y ademas por el SOAP." },
  { id:139, categoria:"seguridad", pregunta:"Que efecto produce el alcohol en la capacidad de conduccion?", opciones:["Mejora la concentracion en dosis bajas","Reduce los reflejos, deteriora el juicio, disminuye la coordinacion, amplia el tiempo de reaccion y produce falsa sensacion de seguridad","Solo afecta a personas sin experiencia al volante","Tiene efecto despues de 2 horas de consumido"], respuesta:1, explicacion:"El alcohol afecta al conductor desde la primera copa: reduce reflejos, deteriora la coordinacion motora, altera el juicio y la percepcion del riesgo, amplia el tiempo de reaccion y produce una peligrosa sensacion de falsa seguridad." },
  { id:140, categoria:"seguridad", pregunta:"Que hacer si el freno de pie falla mientras se conduce?", opciones:["Abrir la puerta y salir del vehiculo","Bajar marchas progresivamente para usar el freno del motor, usar el freno de mano con suavidad y buscar un lugar donde detener el vehiculo de forma segura","Apagar el motor inmediatamente","Tocar la bocina y esperar"], respuesta:1, explicacion:"Si fallan los frenos: 1) No entrar en panico, 2) Bombear el pedal repetidamente (puede recuperar presion), 3) Reducir marcha para usar el freno del motor, 4) Aplicar el freno de mano progresivamente, 5) Buscar un escape como pendiente ascendente o berma de arena." },
  { id:141, categoria:"seguridad", pregunta:"Que es la ZONA DE IMPACTO CERO en algunos estacionamientos?", opciones:["Una zona donde esta prohibido estacionar","Una zona donde la velocidad maxima es 0 km/h","Una zona de estacionamiento disenada para que los conductores puedan abrir las puertas sin golpear el vehiculo del lado","Un area reservada para discapacitados"], respuesta:2, explicacion:"La zona de impacto cero es un espacio adicional en los extremos de las plazas de estacionamiento que permite abrir las puertas del vehiculo sin impactar el auto del costado. Reduce considerablemente los danos entre vehiculos estacionados." },
  { id:142, categoria:"seguridad", pregunta:"Cual es el sistema de retencion infantil correcto para un bebe de 6 meses?", opciones:["Silla de auto orientada hacia adelante en el asiento trasero","Silla de auto orientada hacia ATRAS (contramarcha) en el asiento trasero","Silla de auto orientada hacia adelante en el asiento del copiloto","Sostenido en brazos por el adulto acompanante"], respuesta:1, explicacion:"Los bebes y ninos menores de 15 meses (o hasta los 4 anos segun el modelo) deben ir en silla orientada HACIA ATRAS (contramarcha). Esta posicion distribuye mejor las fuerzas del impacto en la cabeza, cuello y espalda del bebe." },
  { id:143, categoria:"seguridad", pregunta:"Por que es peligroso conducir bajo los efectos de algunos medicamentos de venta libre?", opciones:["Solo los medicamentos de receta afectan la conduccion","Algunos antihistaminicos, ansioliticos, analgesicos y medicamentos para el resfrio pueden causar sueno, vision borrosa y reduccion de reflejos","Los medicamentos de venta libre no tienen efectos secundarios","Solo si se toman en dosis mayores a las indicadas"], respuesta:1, explicacion:"Muchos medicamentos comunes como antihistaminicos (para alergias), analgesicos potentes y preparados para la tos o el resfrio pueden causar sueno, mareos o vision borrosa. Siempre leer el prospecto y consultar al farmaceutico antes de conducir." },
  { id:144, categoria:"seguridad", pregunta:"Que es la SEGURIDAD ACTIVA en un vehiculo?", opciones:["Los sistemas de seguridad que protegen en caso de accidente (airbag, cinturon)","Los sistemas que ayudan al conductor a EVITAR accidentes (ABS, control de estabilidad, frenos, iluminacion)","El seguro del vehiculo","La carroceria reforzada"], respuesta:1, explicacion:"La seguridad activa son todos los sistemas que ayudan a PREVENIR el accidente: ABS, control electronico de estabilidad (ESP), sistemas de asistencia al frenado, buena iluminacion, neumaticos en buen estado, etc." },
  { id:145, categoria:"seguridad", pregunta:"En que consiste la SEGURIDAD PASIVA de un vehiculo?", opciones:["Los sistemas que ayudan a evitar el accidente","Los sistemas que MINIMIZAN LAS CONSECUENCIAS una vez ocurrido el accidente: airbag, cinturon, estructura de la carroceria","El color del vehiculo","Los retrovisores del vehiculo"], respuesta:1, explicacion:"La seguridad pasiva son los sistemas que minimizan las lesiones cuando el accidente ya es inevitable: cinturones de seguridad, airbags, apoyacabezas, zonas de deformacion programada, sellado de puertas, etc." },
  { id:146, categoria:"mecanica", pregunta:"Que funcion cumple el catalizador en el vehiculo?", opciones:["Mejorar el rendimiento del motor","Reducir las emisiones contaminantes de los gases de escape del motor","Filtrar el combustible antes de entrar al motor","Reducir el ruido del motor"], respuesta:1, explicacion:"El catalizador es un dispositivo que convierte los gases de escape toxicos (CO, NOx, HC) del motor en gases menos contaminantes (CO2, N2, H2O) antes de ser expulsados al ambiente. Un catalizador danado puede generar emisiones excesivas y fallar en la revision tecnica." },
  { id:147, categoria:"mecanica", pregunta:"Que es la BANDA DE RODADURA de un neumatico?", opciones:["El dibujo o grabado en la superficie exterior del neumatico que esta en contacto con el suelo","El aro metalico del neumatico","El nucleo interno del neumatico","La presion del aire dentro del neumatico"], respuesta:0, explicacion:"La banda de rodadura es la parte exterior del neumatico que entra en contacto con el asfalto. Su dibujo (ranuras) permite evacuar el agua en superficies mojadas y proporcionar adherencia. Debe tener al menos 1.6 mm de profundidad." },
  { id:148, categoria:"mecanica", pregunta:"Que indica un testigo de ABS encendido permanentemente en el tablero?", opciones:["El ABS esta funcionando correctamente","Hay una falla en el sistema ABS - el vehiculo frena pero sin la asistencia antiderrape, lo que reduce la seguridad","Se debe purgar el liquido de frenos","El vehiculo tiene las 4 ruedas bloqueadas"], respuesta:1, explicacion:"Si el testigo del ABS permanece encendido indica un fallo en el sistema antibloqueo. El vehiculo seguira teniendo frenos convencionales pero sin la asistencia del ABS. Se debe revisar en un taller a la brevedad posible." },
  { id:149, categoria:"mecanica", pregunta:"Por que se recomienda no lavar el motor del vehiculo con agua a presion?", opciones:["Porque dana la pintura del capo","Porque puede ingresar agua a componentes electronicos, cables y conectores, causando cortocircuitos o fallas","Porque enfria el motor demasiado","Porque deja residuos de jabon"], respuesta:1, explicacion:"El motor moderno tiene multitud de sensores, conectores electricos y modulos electronicos sensibles al agua. Un lavado a presion puede introducir agua en estos componentes y causar fallas electricas graves y costosas." },
  { id:150, categoria:"mecanica", pregunta:"Que es el EMBRAGUE en un vehiculo de transmision manual y para que sirve?", opciones:["Un tipo de freno auxiliar","Un mecanismo que permite conectar y desconectar el motor de la transmision para cambiar de marcha sin danos","El pedal de freno","El pedal del acelerador"], respuesta:1, explicacion:"El embrague es el mecanismo que separa temporalmente el motor de la caja de cambios, permitiendo cambiar de marcha sin que los engranajes se danenj. El pedal del embrague es el pedal izquierdo en los vehiculos de cambio manual." },
  { id:151, categoria:"normas", pregunta:"Cual es el orden correcto de prioridad en el trafico cuando todos los elementos coinciden?", opciones:["Semaforo, agente de transito, senalizacion vertical","Agente de transito (Carabineros), luego semaforo, luego senalizacion vertical y horizontal","Senalizacion vertical, semaforo, agente de transito","No hay orden de prioridad"], respuesta:1, explicacion:"El orden de prioridad es: 1) Agente de transito (Carabinero dirigiendo el trafico), 2) Semaforo, 3) Senalizacion vertical (senales de transito), 4) Senalizacion horizontal (marcas en el suelo). El agente humano tiene prioridad sobre todo lo demas." },
  { id:152, categoria:"normas", pregunta:"Que significa la expresion DERECHO DE PASO o PRIORIDAD en el trafico?", opciones:["El derecho a conducir a cualquier velocidad","El derecho de un usuario de la via a circular sin detenerse ante otro usuario","El permiso especial para usar autopistas de pago","El derecho a estacionar en cualquier lugar"], respuesta:1, explicacion:"El derecho de paso o prioridad es el derecho de un vehiculo o peaton a cruzar o circular sin que otro usuario lo interrumpa. La ley establece quien tiene preferencia en cada situacion para ordenar el trafico y prevenir accidentes." },
  { id:153, categoria:"normas", pregunta:"En que parte de la calzada debe circular un ciclista en Chile cuando no hay ciclovia?", opciones:["En el centro de la calzada","Por la vereda (acera)","Por el extremo derecho de la calzada, lo mas cerca posible del borde","Por el carril de buses"], respuesta:2, explicacion:"Cuando no existe ciclovia, el ciclista debe circular por el extremo derecho de la calzada. En Chile la ley reconoce a los ciclistas como parte del trafico y les otorga los mismos derechos y obligaciones que a los vehiculos motorizados." },
  { id:154, categoria:"normas", pregunta:"Esta permitido usar el carril de alta ocupacion (VAO) con un solo ocupante en el vehiculo?", opciones:["Si, pagando un recargo","Si, solo los fines de semana","No, el carril VAO es exclusivo para vehiculos con 2 o mas ocupantes (en algunos casos 3 o mas, segun la via)","Si, en horario nocturno"], respuesta:2, explicacion:"El carril VAO (Vehiculo de Alta Ocupacion) o carril HOV esta reservado para vehiculos con el minimo de ocupantes indicado en la senalizacion (generalmente 2 o mas). Circular en el solo reduce la congestion y premia el uso compartido del auto." },
  { id:155, categoria:"normas", pregunta:"Que obligaciones tiene el conductor involucrado en un accidente de transito en Chile?", opciones:["Puede retirarse si el dano es leve","Prestar auxilio a los heridos, dar informacion a las otras partes, no mover los vehiculos (salvo para liberar heridos), y dar aviso a Carabineros","Solo llamar al seguro","Fotografiar el accidente y retirarse"], respuesta:1, explicacion:"Ante un accidente: prestar auxilio a los heridos, identificarse y dar datos del seguro a las otras partes, no mover los vehiculos (a menos que se deba liberar heridos o que el accidente sea de solo danos materiales), llamar a Carabineros si hay heridos." },
  { id:156, categoria:"normas", pregunta:"Cuantos pasajeros puede llevar un vehiculo particular Clase B en Chile?", opciones:["Sin limite","El numero indicado en la homologacion del vehiculo, que aparece en el permiso de circulacion (generalmente 4 o 5 incluido el conductor)","Solo 4 pasajeros siempre","Depende del tamano del auto"], respuesta:1, explicacion:"Un vehiculo de Clase B solo puede llevar el numero de pasajeros indicado en su homologacion, que aparece en el permiso de circulacion. Transportar mas personas de las permitidas es una infraccion." },
  { id:157, categoria:"normas", pregunta:"Que deben hacer los conductores ante una PROCESION, DESFILE o CORTEJO FUNEBRE que ocupa la calzada?", opciones:["Circular entre los participantes si hay espacio","Tocar la bocina para que se aparten","Detenerse y ceder el paso; no puede interrumpirse un cortejo o desfile","Adelantar rapido por el lado izquierdo"], respuesta:2, explicacion:"Los conductores deben detenerse y ceder el paso ante procesiones, desfiles y cortejos funerarios. Interrumpir un cortejo funebre esta especialmente prohibido por la ley de transito chilena." },
  { id:158, categoria:"normas", pregunta:"Que se entiende por MANEJO A LA DEFENSIVA?", opciones:["Conducir con los seguros del vehiculo puestos","Una tecnica de conduccion que anticipa los errores de los demas usuarios, adapta la velocidad y la posicion para tener tiempo y espacio de reaccion ante cualquier situacion inesperada","Conducir solo por carreteras senalizadas","Conducir con un copiloto que avise de los peligros"], respuesta:1, explicacion:"El manejo a la defensiva es una tecnica que asume que los demas conductores pueden cometer errores. Se basa en anticipar situaciones de peligro, mantener distancias de seguridad, adaptarse a las condiciones de la via y nunca confiar ciegamente en que los demas respetaran las normas." },
  { id:159, categoria:"senales", pregunta:"Que indica una senal de VELOCIDAD MINIMA (numero en blanco sobre fondo azul)?", opciones:["Que el vehiculo no puede superar esa velocidad","Que el vehiculo DEBE circular al menos a esa velocidad en condiciones normales","Que en esa zona hay colas de trafico","La velocidad recomendada en la curva"], respuesta:1, explicacion:"La senal de velocidad minima (fondo azul, numero blanco) indica que en condiciones normales el vehiculo debe circular como minimo a esa velocidad. Generalmente se usa en autopistas para evitar que vehiculos lentos obstaculicen el trafico." },
  { id:160, categoria:"senales", pregunta:"Que indica la senal de FIN DE PROHIBICION (circulo con linea diagonal sobre otra senal)?", opciones:["El inicio de una nueva prohibicion","El final de la restriccion o prohibicion indicada anteriormente por otra senal","Zona de obras terminada","Semaforo proximo"], respuesta:1, explicacion:"La senal de fin de prohibicion (barra diagonal sobre la prohibicion anterior) indica que la restriccion que estaba vigente (velocidad maxima, adelantamiento prohibido, etc.) ha terminado y se vuelven a aplicar las normas generales." },
  { id:161, categoria:"manejo", pregunta:"Que es el MANEJO ECOLOGICO o ECO-DRIVING?", opciones:["Conducir solo autos electricos","Una tecnica de conduccion que busca reducir el consumo de combustible y las emisiones: aceleraciones suaves, anticipacion del trafico y uso del freno del motor","Usar biodiesel en vez de gasolina","Conducir sin aire acondicionado"], respuesta:1, explicacion:"El eco-driving es una tecnica de conduccion eficiente: acelerar progresivamente, mantener una velocidad constante, anticipar el trafico para no frenar bruscamente, usar el freno del motor en bajadas y apagar el motor en paradas largas. Reduce el consumo entre un 10% y 30%." },
  { id:162, categoria:"manejo", pregunta:"Que se debe verificar antes de iniciar un viaje largo en carretera?", opciones:["Solo el nivel de combustible","Nivel de combustible, aceite, agua, frenos, neumaticos (presion y estado), luces, limpiaparabrisas y que los documentos esten al dia","Solo los neumaticos","Solo que el auto arranque bien"], respuesta:1, explicacion:"Antes de un viaje largo se debe revisar: combustible, nivel de aceite, nivel de refrigerante, estado y presion de los 4 neumaticos (mas el de repuesto), funcionamiento de luces y limpiaparabrisas, frenos, y que los documentos (licencia, permiso, RTV, SOAP) esten vigentes." },
  { id:163, categoria:"manejo", pregunta:"Como afecta la CARGA excesiva al comportamiento del vehiculo?", opciones:["No afecta si el vehiculo es grande","Aumenta la distancia de frenado, reduce la maniobrabilidad, puede sobrecargar los neumaticos y afecta la direccion del vehiculo","Solo afecta el consumo de combustible","Mejora la estabilidad en curvas"], respuesta:1, explicacion:"La sobrecarga aumenta la distancia de frenado (mas masa que detener), reduce la maniobrabilidad, puede reventar neumaticos (exceso de presion y calor), sobrecargar el motor y la transmision, y en vehiculos de traccion trasera puede levantar las ruedas delanteras reduciendo la eficacia de la direccion." },
  { id:164, categoria:"manejo", pregunta:"Que se debe hacer al estacionar en una calle donde circulan tranvias (cuando existen)?", opciones:["Estacionar entre los rieles","Estacionar respetando la distancia minima de seguridad de las vias del tranvia","Estacionar sobre los rieles es permitido por corto tiempo","El tranvia siempre se detiene"], respuesta:1, explicacion:"Nunca se debe estacionar sobre los rieles o en la zona de seguridad de los tranvias. Los tranvias tienen un recorrido fijo y no pueden esquivar obstaculos. Hay que respetar las marcas de la via del tranvia." },
  { id:165, categoria:"manejo", pregunta:"Que se debe hacer al circular por una zona de obras con semaforo de carril alternado?", opciones:["Ignorarlo si no hay trabajadores presentes","Respetar el semaforo igual que cualquier otro semaforo: detenerse en rojo y avanzar solo en verde","Pasar rapido en amarillo","Hacer caso solo a las senales del banderero humano, no al semaforo"], respuesta:1, explicacion:"Los semaforos de carril alternado en zonas de obras deben respetarse igual que cualquier semaforo: detencion obligatoria en rojo, precaucion en amarillo y paso en verde. Saltarse estos semaforos puede causar choques frontales con vehiculos que vienen en sentido contrario." },
  { id:166, categoria:"seguridad", pregunta:"Que es un CORREDOR DE EMERGENCIA y como se forma?", opciones:["Una autopista exclusiva para ambulancias","Un carril especial senalizado en la carretera","El espacio que se crea cuando los vehiculos de los carriles extremos se desplazan hacia sus respectivos lados, dejando libre el centro para el paso de vehiculos de emergencia","Una zona de la vereda para camillas"], respuesta:2, explicacion:"El corredor de emergencia es el espacio que se forma cuando los vehiculos que estan detenidos (por accidente o congestion) se desplazan hacia los extremos de la via, dejando libre el carril del medio para el paso de ambulancias, bomberos y policia." },
  { id:167, categoria:"seguridad", pregunta:"Que debe hacer el conductor si sus frenos se recalientan y huelen a quemado en una bajada larga?", opciones:["Seguir conduciendo normal, es inofensivo","Detenerse en un lugar seguro, dejar enfriar los frenos (sin aplicarlos ni mojar con agua) y revisar el sistema antes de continuar","Mojar los frenos con agua para enfriarlos rapidamente","Solo reducir la velocidad y continuar"], respuesta:1, explicacion:"Frenos calientes: detenerse en lugar seguro. NO mojar los frenos con agua fria (el cambio brusco de temperatura puede danar los discos). Dejar enfriar de forma natural. Revisar el nivel de liquido de frenos y el estado de las pastillas antes de continuar." },
  { id:168, categoria:"seguridad", pregunta:"Por que se recomienda que los ninos viajen en el asiento trasero y nunca en el asiento del copiloto con airbag activo?", opciones:["Por comodidad para el conductor","El airbag frontal del copiloto puede lesionar gravemente o matar a un nino pequeno al activarse, ya que esta disenado para adultos","Solo aplica para menores de 1 ano","El asiento trasero es mas comodo para los ninos"], respuesta:1, explicacion:"El airbag del copiloto se activa con gran fuerza y velocidad, disenada para adultos de talla media. En ninos, especialmente los que van en sillas orientadas hacia atras, el airbag puede causar lesiones fatales. Siempre ninos atras, con su silla adecuada." },
  { id:169, categoria:"seguridad", pregunta:"Que se debe hacer si se ve a otro conductor conduciendo de forma peligrosa o temeraria?", opciones:["Hacer lo mismo para advertirle","Perseguirlo para fotografiarlo","Mantener la distancia de seguridad, no competir ni interactuar con el, y si es posible tomar nota de la placa para reportarlo a Carabineros (133)","Tocarle la bocina repetidamente"], respuesta:2, explicacion:"Ante un conductor peligroso: alejarse y mantener distancia (no interactuar, no competir). Si es posible, tomar nota de la placa y describir el vehiculo y situacion para reportarlo al 133 de Carabineros. Nunca perseguirlo ni enfrentarlo." },
  { id:170, categoria:"seguridad", pregunta:"Cual de las siguientes afirmaciones sobre el uso del cinturon de seguridad es CORRECTA?", opciones:["El airbag reemplaza la necesidad del cinturon","En caso de accidente el cinturon puede ser mas danino que beneficioso","El cinturon de seguridad debe usarse siempre, ya que junto con el airbag forma un sistema complementario de proteccion","Solo es necesario en viajes de mas de 30 minutos"], respuesta:2, explicacion:"El cinturon es siempre obligatorio. Sin cinturon el airbag puede incluso MATAR al ocupante al activarse. El cinturon mantiene al ocupante en posicion correcta para que el airbag funcione como esta disenado. Son sistemas complementarios, no alternativos." },
];

